/**
 * Bootstrap Components Bundle
 * Imports Bootstrap for automatic component initialization via data attributes
 */

// Import Bootstrap - this enables all Bootstrap components to work via data-bs-* attributes
// import 'bootstrap';
import 'bootstrap/js/dist/collapse';
import 'bootstrap/js/dist/dropdown';


// Bootstrap 5.3+ automatically initializes components via data-bs-toggle attributes
// No manual initialization needed for:
// - Collapse (mobile menu) - works via data-bs-toggle="collapse"
// - Dropdown (navigation) - works via data-bs-toggle="dropdown"

